changeSet.sql:
-- Legacy domain uniqueness is case-sensitive. Keep every merchant integration, but let only -- the active/most-recent merchant claim a verified domain when normalization creates a collision. WITH normalized_merchants AS ( SELECT merchant.*, nullif(lower(trim(trailing '.' from btrim(merchant.domain))), '') AS normalized_domain FROM merchant ), ranked_merchants AS ( SELECT normalized_merchants.*, row_number() OVER ( PARTITION BY normalized_domain ORDER BY active DESC, updated_at DESC NULLS LAST, created_at DESC NULLS LAST, id ) AS normalized_domain_rank FROM normalized_merchants ) INSERT INTO merchant_integration ( id, merchant_id, provider, kind, external_merchant_id, verified_domain, verified_shop_identity, endpoint, protocol_version, auth_strategy, status, source, raw_metadata, captured_at, created_at, updated_at ) SELECT gen_random_uuid(), merchant.id, 'GENERIC_UCP', 'MERCHANT_CONNECTION', NULL, CASE WHEN merchant.normalized_domain_rank = 1 THEN merchant.normalized_domain ELSE NULL END, NULL, coalesce( nullif(btrim(merchant.advertised_mcp_endpoint), ''), nullif(btrim(merchant.profile_mcp_endpoint), ''), btrim(merchant.ucp_url) ), nullif(btrim(merchant.ucp_version), ''), 'NONE', CASE WHEN merchant.active THEN 'ACTIVE' ELSE 'INACTIVE' END, 'LEGACY_MERCHANT_BACKFILL', merchant.profile_raw, coalesce( merchant.profile_captured_at, merchant.last_profiled_at, merchant.updated_at, merchant.created_at, CURRENT_TIMESTAMP ), coalesce(merchant.created_at, CURRENT_TIMESTAMP), coalesce(merchant.updated_at, merchant.created_at, CURRENT_TIMESTAMP) FROM ranked_merchants merchant WHERE NOT EXISTS ( SELECT 1 FROM merchant_integration existing WHERE existing.merchant_id = merchant.id AND existing.provider = 'GENERIC_UCP' AND existing.endpoint = coalesce( nullif(btrim(merchant.advertised_mcp_endpoint), ''), nullif(btrim(merchant.profile_mcp_endpoint), ''), btrim(merchant.ucp_url) ) );
INSERT INTO merchant_integration_role (merchant_integration_id, role) SELECT integration.id, 'STOREFRONT_CATALOG' FROM merchant_integration integration WHERE integration.provider = 'GENERIC_UCP' AND integration.source = 'LEGACY_MERCHANT_BACKFILL' ON CONFLICT DO NOTHING;
INSERT INTO merchant_integration_role (merchant_integration_id, role) SELECT integration.id, 'CART' FROM merchant_integration integration JOIN merchant ON merchant.id = integration.merchant_id JOIN merchant_raw ON merchant_raw.id = merchant.merchant_raw_id WHERE integration.provider = 'GENERIC_UCP' AND integration.source = 'LEGACY_MERCHANT_BACKFILL' AND merchant_raw.has_cart_management ON CONFLICT DO NOTHING;
INSERT INTO merchant_integration_role (merchant_integration_id, role) SELECT integration.id, 'CHECKOUT' FROM merchant_integration integration JOIN merchant ON merchant.id = integration.merchant_id JOIN merchant_raw ON merchant_raw.id = merchant.merchant_raw_id WHERE integration.provider = 'GENERIC_UCP' AND integration.source = 'LEGACY_MERCHANT_BACKFILL' AND merchant_raw.has_checkout ON CONFLICT DO NOTHING;
INSERT INTO merchant_integration_role (merchant_integration_id, role) SELECT integration.id, 'ORDERS' FROM merchant_integration integration JOIN merchant ON merchant.id = integration.merchant_id JOIN merchant_raw ON merchant_raw.id = merchant.merchant_raw_id WHERE integration.provider = 'GENERIC_UCP' AND integration.source = 'LEGACY_MERCHANT_BACKFILL' AND merchant_raw.has_order ON CONFLICT DO NOTHING;

CREATE UNIQUE INDEX uk_merchant_integration_provider_external_identity
ON merchant_integration (provider, external_merchant_id)
WHERE external_merchant_id IS NOT NULL;

CREATE UNIQUE INDEX uk_merchant_integration_provider_verified_domain
ON merchant_integration (lower(verified_domain), provider)
WHERE verified_domain IS NOT NULL;

CREATE UNIQUE INDEX uk_merchant_integration_provider_shop_identity
ON merchant_integration (provider, lower(verified_shop_identity))
WHERE verified_shop_identity IS NOT NULL;
